const pred = $input.first().json;

const statusEntries = Object.entries(pred.club_status_distribution || {})
  .map(([k, v]) => `${k}: ${v}`)
  .join(', ');

const prompt = `Tu es l assistant analytique de la plateforme H&M Retail Intelligence. Voici un resume du scoring client genere le ${pred.generated_at} sur ${pred.n_customers_scored} clients (table ${pred.source_table}) : statut club dominant : ${pred.dominant_club_status} (repartition : ${statusEntries}). Segment dominant (clustering) : ${pred.dominant_segment}. Depense totale predite : ${pred.predicted_spend_total} (moyenne par client : ${pred.predicted_spend_mean}, mediane : ${pred.predicted_spend_median}). Redige un message professionnel et concis de 4 a 5 phrases en francais a destination de l equipe marketing/CRM. Mentionne le statut club dominant, le segment dominant et la depense predite, puis donne 1 a 2 recommandations concretes (ex. ciblage d une campagne, relance d un segment a risque).`;

return [{
  json: {
    prompt: prompt,
    prediction: pred
  }
}];

// Formate le payload attendu par Django SSE (receive_daily_report) et par le
// Dashboard.tsx (PredictionData interface) -- ce backend Django n'existe pas
// dans ce depot (voir README.md section 2 'Ce qui n'est pas implemente') ; ce
// noeud reste donc utile localement (payload pret a inspecter) mais l'appel
// HTTP suivant ('Push SSE -> Django') echouera tant qu'aucun backend Django
// n'est deploye a l'URL configuree.
const llmText = $input.first().json.text?.trim();
const pred = $('Préparer Prompt Ollama').first().json.prediction;

const payload = {
  type: 'llm_report',
  date: pred.generated_at,
  generated_at: new Date().toISOString(),
  message: llmText,
  prediction: {
    n_customers_scored: pred.n_customers_scored,
    dominant_club_status: pred.dominant_club_status,
    dominant_segment: String(pred.dominant_segment),
    predicted_spend_total: pred.predicted_spend_total,
    predicted_spend_mean: pred.predicted_spend_mean
  }
};

return [{ json: payload }];
